import { describe, expect, it } from 'vitest';
import { CounterStore, Store } from './Store';

describe('Chapter 4 counters', () => {
  it('starts a collection with one zero-valued counter', () => {
    const store = new Store();
    expect(store.counters).toHaveLength(1);
    expect(store.counters[0].value).toBe(0);
  });

  it('adds a delta to an edited value', () => {
    const counter = new CounterStore();
    counter.setValue(42);
    counter.add(1);
    expect(counter.value).toBe(43);
    counter.add(-45);
    expect(counter.value).toBe(-2);
  });

  it.todo('ignores non-finite edits and deltas');

  it.todo('frees a slot after reaching capacity');

  it.todo('resets one counter and updates the total');
});

