    makeAutoObservable(this, { id: false }, { autoBind: true });
  }

  add(delta: number) {
    const next = this.value + delta;
    if (Number.isFinite(delta) && Number.isFinite(next)) this.value = next;
  }

  setValue(value: number) {
    if (Number.isFinite(value)) this.value = value;
  }

  reset() {
    this.value = 0;
  }
}

